        ExchangeEntity::class,
        ExchangeItemEntity::class,
        AppSettingsEntity::class,
        AuditLogEntity::class
    ],
    version = 1,
    exportSchema = true
)
abstract class PosDatabase : RoomDatabase() {
    abstract fun vendorDao(): VendorDao
    abstract fun categoryDao(): CategoryDao
    abstract fun productDao(): ProductDao
    abstract fun customerDao(): CustomerDao
    abstract fun saleDao(): SaleDao
    abstract fun stockMovementDao(): StockMovementDao
    abstract fun exchangeDao(): ExchangeDao
    abstract fun settingsDao(): SettingsDao
    abstract fun auditLogDao(): AuditLogDao

    companion object {
        const val DB_NAME = "bazar_pos.db"

        @Volatile
        private var INSTANCE: PosDatabase? = null

        // Example schema migration template for future upgrades
        val MIGRATION_1_2 = object : Migration(1, 2) {
            override fun migrate(db: SupportSQLiteDatabase) {
                // Preserved for forward-compatible schema evolution
            }
        }

        fun getInstance(context: Context): PosDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    PosDatabase::class.java,
                    DB_NAME
                )
                    .addCallback(object : Callback() {
                        override fun onCreate(db: SupportSQLiteDatabase) {
                            super.onCreate(db)
                            db.execSQL(
                                """
                                INSERT OR IGNORE INTO app_settings (
                                    id, storeName, storeAddress, storePhone, storeLogoUri,
                                    currencySymbol, language, darkTheme, paperWidthMm,
                                    lastPrinterName, lastPrinterAddress, autoPrintReceipt,
                                    lowStockAlertEnabled, englishReturnPolicy, banglaReturnPolicy,
                                    receiptFooterNote, adminPasswordHash, adminPasswordSalt,
                                    protectProductOps, protectVendorOps, protectCategoryOps,
                                    protectStockAdjust, protectPosRemoval, protectPosDiscount,
                                    protectBillCancel, protectSensitiveReports
                                ) VALUES (
                                    1, 'BazarPOS Retail Store', 'Dhaka, Bangladesh', '+880 1700-000000', '',
                                    '৳', 'en', 0, 58,
                                    '', '', 1,
                                    1,
                                    'Products may be exchanged within 3 days of purchase with the original bill. No cash refund is available.',
                                    'ক্রয়ের ৩ দিনের মধ্যে মূল বিলসহ পণ্য এক্সচেঞ্জ করা যাবে। কোনো নগদ টাকা ফেরত দেওয়া হবে না।',
                                    'Thank you for shopping with us!', '', '',
                                    1, 1, 1, 1, 1, 1, 1, 0
                                )
                                """.trimIndent()
                            )
                        }
                    })
                    .build()
                INSTANCE = instance
                instance
            }
        }

        fun closeAndReset() {
            synchronized(this) {
                INSTANCE?.close()
                INSTANCE = null
            }
        }
    }
}

package com.bazarpos.retail.data.local.dao

import androidx.room.Dao
import androidx.room.Delete
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Transaction
import androidx.room.Update
import com.bazarpos.retail.data.local.entity.*
import kotlinx.coroutines.flow.Flow

@Dao
interface VendorDao {
    @Query("SELECT * FROM vendors ORDER BY id DESC")
    fun observeAll(): Flow<List<VendorEntity>>

    @Query("SELECT * FROM vendors ORDER BY name ASC")
    suspend fun getAll(): List<VendorEntity>

    @Query("SELECT * FROM vendors WHERE id = :id")
    suspend fun getById(id: Long): VendorEntity?

    @Query("SELECT COUNT(*) FROM vendors")
    suspend fun count(): Int

    @Query("SELECT MAX(id) FROM vendors")
    suspend fun maxId(): Long?

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insert(vendor: VendorEntity): Long

    @Update
    suspend fun update(vendor: VendorEntity)

    @Delete
    suspend fun delete(vendor: VendorEntity)
}

@Dao
interface CategoryDao {
    @Transaction
    @Query("SELECT * FROM categories ORDER BY name ASC")
    fun observeAllWithSubcategories(): Flow<List<CategoryWithSubcategories>>

    @Query("SELECT * FROM categories ORDER BY name ASC")
    suspend fun getAll(): List<CategoryEntity>

    @Query("SELECT MAX(id) FROM categories")
    suspend fun maxCategoryId(): Long?

    @Query("SELECT MAX(id) FROM subcategories")
    suspend fun maxSubcategoryId(): Long?

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insertCategory(category: CategoryEntity): Long

    @Update
    suspend fun updateCategory(category: CategoryEntity)

    @Delete
    suspend fun deleteCategory(category: CategoryEntity)

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insertSubcategory(subcategory: SubcategoryEntity): Long

    @Update
    suspend fun updateSubcategory(subcategory: SubcategoryEntity)

    @Delete
    suspend fun deleteSubcategory(subcategory: SubcategoryEntity)

    @Query("SELECT COUNT(*) FROM products WHERE categoryId = :categoryId")
    suspend fun countProductsInCategory(categoryId: Long): Int

    @Query("SELECT COUNT(*) FROM products WHERE subcategoryId = :subcategoryId")
    suspend fun countProductsInSubcategory(subcategoryId: Long): Int
}

@Dao
interface ProductDao {
    @Query("SELECT * FROM products ORDER BY id DESC")
    fun observeAll(): Flow<List<ProductEntity>>

    @Query("SELECT * FROM products ORDER BY name ASC")
    suspend fun getAll(): List<ProductEntity>

    @Query("SELECT * FROM products WHERE id = :id")
    suspend fun getById(id: Long): ProductEntity?

    @Query("SELECT * FROM products WHERE barcode = :barcode LIMIT 1")
    suspend fun getByBarcode(barcode: String): ProductEntity?

    @Query("SELECT * FROM products WHERE vendorId = :vendorId ORDER BY name ASC")
    fun observeByVendor(vendorId: Long): Flow<List<ProductEntity>>

    @Query("SELECT MAX(id) FROM products")
    suspend fun maxId(): Long?

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insert(product: ProductEntity): Long

    @Update
    suspend fun update(product: ProductEntity)

    @Delete
    suspend fun delete(product: ProductEntity)

    @Query("UPDATE products SET currentStock = :newStock WHERE id = :productId")
    suspend fun updateStock(productId: Long, newStock: Double)
}

@Dao
interface CustomerDao {
    @Query("SELECT * FROM customers ORDER BY lastPurchaseAt DESC")
    fun observeAll(): Flow<List<CustomerEntity>>

    @Query("SELECT * FROM customers WHERE mobile = :mobile LIMIT 1")
    suspend fun getByMobile(mobile: String): CustomerEntity?

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insert(customer: CustomerEntity): Long

    @Update
    suspend fun update(customer: CustomerEntity)
}

@Dao
interface SaleDao {
    @Transaction
    @Query("SELECT * FROM sales ORDER BY createdAt DESC")
    fun observeAllWithItems(): Flow<List<SaleWithItems>>

    @Transaction
    @Query("SELECT * FROM sales WHERE id = :saleId")
    suspend fun getSaleWithItems(saleId: Long): SaleWithItems?

    @Transaction
    @Query("SELECT * FROM sales WHERE billNumber = :billNumber LIMIT 1")
    suspend fun getByBillNumber(billNumber: String): SaleWithItems?

    @Query("SELECT MAX(billNumber) FROM sales WHERE billDateKey = :dateKey")
    suspend fun getMaxBillNumberForDate(dateKey: String): String?

    @Query("SELECT * FROM sales WHERE createdAt BETWEEN :fromMillis AND :toMillis ORDER BY createdAt DESC")
    suspend fun getSalesBetween(fromMillis: Long, toMillis: Long): List<SaleEntity>

    @Query("SELECT * FROM sale_items WHERE saleId IN (SELECT id FROM sales WHERE createdAt BETWEEN :fromMillis AND :toMillis AND status != 'CANCELLED')")
    suspend fun getSaleItemsBetween(fromMillis: Long, toMillis: Long): List<SaleItemEntity>

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insertSale(sale: SaleEntity): Long

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insertSaleItems(items: List<SaleItemEntity>)

    @Query("UPDATE sales SET status = :status WHERE id = :saleId")
    suspend fun updateStatus(saleId: Long, status: String)
}

@Dao
interface StockMovementDao {
    @Query("SELECT * FROM stock_movements ORDER BY createdAt DESC LIMIT 500")
    fun observeRecent(): Flow<List<StockMovementEntity>>

    @Query("SELECT * FROM stock_movements WHERE productId = :productId ORDER BY createdAt DESC")
    fun observeByProduct(productId: Long): Flow<List<StockMovementEntity>>

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insert(movement: StockMovementEntity): Long
}

@Dao
interface ExchangeDao {
    @Transaction
    @Query("SELECT * FROM exchanges ORDER BY createdAt DESC")
    fun observeAllWithItems(): Flow<List<ExchangeWithItems>>

    @Query("SELECT COUNT(*) FROM exchanges")
    suspend fun count(): Int

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insertExchange(exchange: ExchangeEntity): Long

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insertExchangeItems(items: List<ExchangeItemEntity>)
}

@Dao
interface SettingsDao {
    @Query("SELECT * FROM app_settings WHERE id = 1")
    fun observeSettings(): Flow<AppSettingsEntity?>

    @Query("SELECT * FROM app_settings WHERE id = 1")
    suspend fun getSettings(): AppSettingsEntity?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsert(settings: AppSettingsEntity)
}

@Dao
interface AuditLogDao {
    @Query("SELECT * FROM audit_logs ORDER BY createdAt DESC LIMIT 300")
    fun observeRecent(): Flow<List<AuditLogEntity>>

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insert(log: AuditLogEntity): Long
}

package com.bazarpos.retail.data.repository

import androidx.room.withTransaction
import com.bazarpos.retail.data.local.PosDatabase
import com.bazarpos.retail.data.local.entity.*
import com.bazarpos.retail.domain.BillNumberGenerator
import com.bazarpos.retail.domain.DhakaTime
import com.bazarpos.retail.domain.ExchangePolicy
import com.bazarpos.retail.domain.GpCalculator
import kotlinx.coroutines.flow.Flow

data class CartLineInput(
    val productId: Long,
    val quantity: Double,
    val unitPrice: Double
)

data class ExchangeLineInput(
    val productId: Long,
    val quantity: Double,
    val unitPrice: Double
)

class PosRepository(private val db: PosDatabase) {
    private val vendorDao = db.vendorDao()
    private val categoryDao = db.categoryDao()
    private val productDao = db.productDao()
    private val customerDao = db.customerDao()
    private val saleDao = db.saleDao()
    private val stockMovementDao = db.stockMovementDao()
    private val exchangeDao = db.exchangeDao()
    private val settingsDao = db.settingsDao()
    private val auditLogDao = db.auditLogDao()

    val vendorsFlow: Flow<List<VendorEntity>> = vendorDao.observeAll()
    val categoriesFlow: Flow<List<CategoryWithSubcategories>> = categoryDao.observeAllWithSubcategories()
    val productsFlow: Flow<List<ProductEntity>> = productDao.observeAll()
    val customersFlow: Flow<List<CustomerEntity>> = customerDao.observeAll()
    val salesFlow: Flow<List<SaleWithItems>> = saleDao.observeAllWithItems()
    val stockMovementsFlow: Flow<List<StockMovementEntity>> = stockMovementDao.observeRecent()
    val exchangesFlow: Flow<List<ExchangeWithItems>> = exchangeDao.observeAllWithItems()
    val settingsFlow: Flow<AppSettingsEntity?> = settingsDao.observeSettings()
    val auditLogsFlow: Flow<List<AuditLogEntity>> = auditLogDao.observeRecent()

    suspend fun getSettings(): AppSettingsEntity {
        return settingsDao.getSettings() ?: AppSettingsEntity().also { settingsDao.upsert(it) }
    }

    suspend fun saveSettings(settings: AppSettingsEntity) {
        settingsDao.upsert(settings)
    }

    suspend fun logAudit(actionType: String, targetReference: String, details: String) {
        auditLogDao.insert(
            AuditLogEntity(
                actionType = actionType,
                targetReference = targetReference,
                details = details
            )
        )
    }

    suspend fun saveVendor(vendor: VendorEntity, isEdit: Boolean): Long {
        return if (isEdit) {
            vendorDao.update(vendor)
            vendor.id
        } else {
            val code = BillNumberGenerator.nextCode("VND", vendorDao.maxId())
            vendorDao.insert(vendor.copy(vendorCode = code))
        }
    }

    suspend fun deleteVendor(vendor: VendorEntity) {
        vendorDao.delete(vendor)
    }

    suspend fun saveCategory(name: String, description: String, existing: CategoryEntity? = null): Long {
        return if (existing != null) {
            categoryDao.updateCategory(existing.copy(name = name.trim(), description = description.trim()))
            existing.id
        } else {
            val code = BillNumberGenerator.nextCode("CAT", categoryDao.maxCategoryId(), 3)
            categoryDao.insertCategory(CategoryEntity(categoryCode = code, name = name.trim(), description = description.trim()))
        }
    }

    suspend fun deleteCategoryIfEmpty(category: CategoryEntity): Result<Unit> {
        val count = categoryDao.countProductsInCategory(category.id)
        if (count > 0) {
            return Result.failure(IllegalStateException("Cannot delete category containing $count product(s). Reassign products first."))
        }
        categoryDao.deleteCategory(category)
        return Result.success(Unit)
    }

    suspend fun saveSubcategory(categoryId: Long, name: String, existing: SubcategoryEntity? = null): Long {
        return if (existing != null) {
            categoryDao.updateSubcategory(existing.copy(name = name.trim()))
            existing.id
        } else {
            val code = BillNumberGenerator.nextCode("SUB", categoryDao.maxSubcategoryId(), 3)
            categoryDao.insertSubcategory(SubcategoryEntity(subcategoryCode = code, categoryId = categoryId, name = name.trim()))
        }
    }

    suspend fun deleteSubcategoryIfEmpty(subcategory: SubcategoryEntity): Result<Unit> {
        val count = categoryDao.countProductsInSubcategory(subcategory.id)
        if (count > 0) {
            return Result.failure(IllegalStateException("Cannot delete subcategory containing $count product(s)."))
        }
        categoryDao.deleteSubcategory(subcategory)
        return Result.success(Unit)
    }

    suspend fun saveProduct(
        product: ProductEntity,
        isEdit: Boolean,
        authorizedByAdmin: Boolean
    ): Result<Long> = db.withTransaction {
        val normalizedBarcode = product.barcode.trim()
        val duplicate = productDao.getByBarcode(normalizedBarcode)
        if (duplicate != null && (!isEdit || duplicate.id != product.id)) {
            return@withTransaction Result.failure(IllegalArgumentException("Duplicate barcode '$normalizedBarcode' already registered to ${duplicate.name}."))
        }

        val gp = GpCalculator.calculate(product.purchasePrice, product.sellingPrice)
        if (isEdit) {
            val updated = product.copy(
                barcode = normalizedBarcode,
                gpAmount = gp.gpAmount,
                gpPercentage = gp.gpPercentage
            )
            productDao.update(updated)
            Result.success(updated.id)
        } else {
            val code = BillNumberGenerator.nextCode("PRD", productDao.maxId())
            val insertedId = productDao.insert(
                product.copy(
                    productCode = code,
                    barcode = normalizedBarcode,
                    gpAmount = gp.gpAmount,
                    gpPercentage = gp.gpPercentage
                )
            )
            if (product.currentStock > 0) {
                stockMovementDao.insert(
                    StockMovementEntity(
                        productId = insertedId,
                        productName = product.name,
                        barcode = normalizedBarcode,
                        movementType = "INITIAL",
                        quantity = product.currentStock,
                        previousStock = 0.0,
                        newStock = product.currentStock,
                        authorizedByAdmin = authorizedByAdmin,
                        note = "Initial stock on registration"
                    )
                )
            }
            Result.success(insertedId)
        }
    }

    suspend fun deleteProduct(product: ProductEntity) {
        productDao.delete(product)
    }

    suspend fun findProductByBarcode(barcode: String): ProductEntity? {
        return productDao.getByBarcode(barcode.trim())
    }

    suspend fun adjustStock(
        productId: Long,
        delta: Double,
        movementType: String,
        note: String,
        authorizedByAdmin: Boolean
    ): Result<Unit> = db.withTransaction {
        val product = productDao.getById(productId)
            ?: return@withTransaction Result.failure(IllegalArgumentException("Product not found"))
        val newStock = (product.currentStock + delta).coerceAtLeast(0.0)
        productDao.updateStock(product.id, newStock)
        stockMovementDao.insert(
            StockMovementEntity(
                productId = product.id,
                productName = product.name,
                barcode = product.barcode,
                movementType = movementType,
                quantity = delta,
                previousStock = product.currentStock,
                newStock = newStock,
                authorizedByAdmin = authorizedByAdmin,
                note = note
            )
        )
        if (authorizedByAdmin) {
            auditLogDao.insert(
                AuditLogEntity(
                    actionType = "STOCK_ADJUSTMENT",
                    targetReference = product.productCode,
                    details = "${product.name}: ${product.currentStock} -> $newStock ($note)"
                )
            )
        }
        Result.success(Unit)
    }

    /**
     * Single atomic Room transaction for:
     * 1. Generating unique YYYYMMDD-001 bill number in Asia/Dhaka timezone
     * 2. Validating stock & deducting quantities
     * 3. Upserting customer record (if mobile provided)
     * 4. Saving Sale + SaleItems + StockMovements
     */
    suspend fun completeSale(
        lines: List<CartLineInput>,
        discountAmount: Double,
        customerName: String,
        customerMobile: String,
        allowOverStockOverride: Boolean
    ): Result<SaleWithItems> = db.withTransaction {
        if (lines.isEmpty()) {
            return@withTransaction Result.failure(IllegalStateException("Cart is empty"))
        }

        val now = System.currentTimeMillis()
        val dateKey = DhakaTime.todayDateKey(now)
        val latestForDay = saleDao.getMaxBillNumberForDate(dateKey)
        val billNumber = BillNumberGenerator.nextBillNumber(dateKey, latestForDay)

        var subtotal = 0.0
        var totalQty = 0.0
        val resolvedProducts = mutableListOf<Pair<ProductEntity, CartLineInput>>()

        for (line in lines) {
            val product = productDao.getById(line.productId)
                ?: return@withTransaction Result.failure(IllegalStateException("Product ID ${line.productId} missing"))
            if (!allowOverStockOverride && line.quantity > product.currentStock) {
                return@withTransaction Result.failure(
                    IllegalStateException("Insufficient stock for ${product.name} (Available: ${product.currentStock})")
                )
            }
            subtotal += GpCalculator.round2(line.unitPrice * line.quantity)
            totalQty += line.quantity
            resolvedProducts += product to line
        }

        val safeDiscount = discountAmount.coerceIn(0.0, subtotal)
        val grandTotal = GpCalculator.round2(subtotal - safeDiscount)

        val cleanMobile = customerMobile.trim()
        val cleanName = customerName.trim()
        var customerId: Long? = null
        if (cleanMobile.isNotBlank()) {
            val existing = customerDao.getByMobile(cleanMobile)
            customerId = if (existing == null) {
                customerDao.insert(
                    CustomerEntity(
                        name = cleanName.ifBlank { "Walk-in Customer" },
                        mobile = cleanMobile,
                        totalSpent = grandTotal,
                        billCount = 1,
                        lastPurchaseAt = now
                    )
                )
            } else {
                customerDao.update(
                    existing.copy(
                        name = cleanName.ifBlank { existing.name },
                        totalSpent = GpCalculator.round2(existing.totalSpent + grandTotal),
                        billCount = existing.billCount + 1,
                        lastPurchaseAt = now
                    )
                )
                existing.id
            }
        }

        val saleId = saleDao.insertSale(
            SaleEntity(
                billNumber = billNumber,
                billDateKey = dateKey,
                customerId = customerId,
                customerName = cleanName,
                customerMobile = cleanMobile,
                subtotal = GpCalculator.round2(subtotal),
                discountAmount = GpCalculator.round2(safeDiscount),
                grandTotal = grandTotal,
                totalQuantity = totalQty,
                status = "COMPLETED",
                createdAt = now
            )
        )

        val saleItems = mutableListOf<SaleItemEntity>()
        for ((product, line) in resolvedProducts) {
            val lineSub = GpCalculator.round2(line.unitPrice * line.quantity)
            saleItems += SaleItemEntity(
                saleId = saleId,
                productId = product.id,
                productName = product.name,
                barcode = product.barcode,
                unit = product.unit,
                quantity = line.quantity,
                unitPrice = line.unitPrice,
                purchasePriceAtSale = product.purchasePrice,
                subtotal = lineSub
            )

            val newStock = (product.currentStock - line.quantity).coerceAtLeast(0.0)
            productDao.updateStock(product.id, newStock)
            stockMovementDao.insert(
                StockMovementEntity(
                    productId = product.id,
                    productName = product.name,
                    barcode = product.barcode,
                    movementType = "SALE",
                    quantity = -line.quantity,
                    previousStock = product.currentStock,
                    newStock = newStock,
                    referenceBillId = billNumber,
                    authorizedByAdmin = allowOverStockOverride,
                    note = "POS Sale $billNumber",
                    createdAt = now
                )
            )
        }
        saleDao.insertSaleItems(saleItems)

        if (safeDiscount > 0.0) {
            auditLogDao.insert(
                AuditLogEntity(
                    actionType = "POS_DISCOUNT",
                    targetReference = billNumber,
                    details = "Authorized discount of ৳$safeDiscount on bill $billNumber"
                )
            )
        }

        val saved = saleDao.getSaleWithItems(saleId)
            ?: return@withTransaction Result.failure(IllegalStateException("Failed to reload saved bill"))
        Result.success(saved)
    }

    /**
     * 3-day Exchange processing (No cash refunds; original sale record preserved).
     */
    suspend fun processExchange(
        originalSaleId: Long,
        returnedLines: List<ExchangeLineInput>,
        replacementLines: List<ExchangeLineInput>,
        reason: String
    ): Result<ExchangeEntity> = db.withTransaction {
        val original = saleDao.getSaleWithItems(originalSaleId)
            ?: return@withTransaction Result.failure(IllegalArgumentException("Original bill not found"))
        if (!ExchangePolicy.isEligibleForExchange(original.sale.createdAt)) {
            return@withTransaction Result.failure(IllegalStateException("Exchange window expired (must be within 3 days of purchase)."))
        }
        if (returnedLines.isEmpty()) {
            return@withTransaction Result.failure(IllegalArgumentException("Select at least one item to return."))
        }

        val now = System.currentTimeMillis()
        val returnedTotal = GpCalculator.round2(returnedLines.sumOf { it.quantity * it.unitPrice })
        val replacementTotal = GpCalculator.round2(replacementLines.sumOf { it.quantity * it.unitPrice })
        val netDiff = GpCalculator.round2(replacementTotal - returnedTotal)

        if (netDiff < 0.0) {
            return@withTransaction Result.failure(
                IllegalStateException("No cash refund is available. Replacement value must be >= returned value.")
            )
        }

        val exNumber = "EXC-${DhakaTime.todayDateKey(now)}-${(exchangeDao.count() + 1).toString().padStart(3, '0')}"
        val exchangeId = exchangeDao.insertExchange(
            ExchangeEntity(
                exchangeNumber = exNumber,
                originalSaleId = original.sale.id,
                originalBillNumber = original.sale.billNumber,
                returnedTotal = returnedTotal,
                replacementTotal = replacementTotal,
                netDifference = netDiff,
                reason = reason,
                authorizedByAdmin = true,
                createdAt = now
            )
        )

        val exchangeItems = mutableListOf<ExchangeItemEntity>()
        for (ret in returnedLines) {
            val product = productDao.getById(ret.productId) ?: continue
            val newStock = product.currentStock + ret.quantity
            productDao.updateStock(product.id, newStock)
            stockMovementDao.insert(
                StockMovementEntity(
                    productId = product.id,
                    productName = product.name,
                    barcode = product.barcode,
                    movementType = "EXCHANGE_RETURN",
                    quantity = ret.quantity,
                    previousStock = product.currentStock,
                    newStock = newStock,
                    referenceBillId = original.sale.billNumber,
                    authorizedByAdmin = true,
                    note = "Returned via $exNumber",
                    createdAt = now
                )
            )
            exchangeItems += ExchangeItemEntity(
                exchangeId = exchangeId,
                productId = product.id,
                productName = product.name,
                barcode = product.barcode,
                direction = "RETURNED",
                quantity = ret.quantity,
                unitPrice = ret.unitPrice,
                subtotal = GpCalculator.round2(ret.quantity * ret.unitPrice)
            )
        }

        for (rep in replacementLines) {
            val product = productDao.getById(rep.productId)
                ?: return@withTransaction Result.failure(IllegalStateException("Replacement product missing"))
            if (rep.quantity > product.currentStock) {
                return@withTransaction Result.failure(IllegalStateException("Insufficient stock for replacement ${product.name}"))
            }
            val newStock = product.currentStock - rep.quantity
            productDao.updateStock(product.id, newStock)
            stockMovementDao.insert(
                StockMovementEntity(
                    productId = product.id,
                    productName = product.name,
                    barcode = product.barcode,
                    movementType = "EXCHANGE_OUT",
                    quantity = -rep.quantity,
                    previousStock = product.currentStock,
                    newStock = newStock,
                    referenceBillId = original.sale.billNumber,
                    authorizedByAdmin = true,
                    note = "Replacement via $exNumber",
                    createdAt = now
                )
            )
            exchangeItems += ExchangeItemEntity(
                exchangeId = exchangeId,
                productId = product.id,
                productName = product.name,
                barcode = product.barcode,
                direction = "REPLACEMENT",
                quantity = rep.quantity,
                unitPrice = rep.unitPrice,
                subtotal = GpCalculator.round2(rep.quantity * rep.unitPrice)
            )
        }

        exchangeDao.insertExchangeItems(exchangeItems)
        saleDao.updateStatus(original.sale.id, "EXCHANGED")
        auditLogDao.insert(
            AuditLogEntity(
                actionType = "EXCHANGE_PROCESSED",
                targetReference = original.sale.billNumber,
                details = "Exchange $exNumber linked to ${original.sale.billNumber}. Net diff: ৳$netDiff"
            )
        )

        Result.success(
            ExchangeEntity(
                id = exchangeId,
                exchangeNumber = exNumber,
                originalSaleId = original.sale.id,
                originalBillNumber = original.sale.billNumber,
                returnedTotal = returnedTotal,
                replacementTotal = replacementTotal,
                netDifference = netDiff,
                reason = reason,
                authorizedByAdmin = true,
                createdAt = now
            )
        )
    }

    suspend fun getSalesBetween(fromMillis: Long, toMillis: Long): List<SaleEntity> =
        saleDao.getSalesBetween(fromMillis, toMillis)

    suspend fun getSaleItemsBetween(fromMillis: Long, toMillis: Long): List<SaleItemEntity> =
        saleDao.getSaleItemsBetween(fromMillis, toMillis)
}

package com.bazarpos.retail.domain

import android.content.Context
import android.net.Uri
import com.bazarpos.retail.data.local.PosDatabase
import com.bazarpos.retail.data.local.entity.ProductEntity
import com.bazarpos.retail.data.local.entity.SaleWithItems
import com.bazarpos.retail.data.local.entity.VendorEntity
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream

object BackupRestoreManager {

    suspend fun exportDatabaseToUri(context: Context, targetUri: Uri): Result<Unit> = withContext(Dispatchers.IO) {
        try {
            val db = PosDatabase.getInstance(context)
            // Flush SQLite WAL journal into main db file before copying
            db.openHelper.writableDatabase.query("PRAGMA wal_checkpoint(FULL)").close()
            val dbFile: File = context.getDatabasePath(PosDatabase.DB_NAME)
            if (!dbFile.exists()) {
                return@withContext Result.failure(IllegalStateException("Database file not found"))
            }
            context.contentResolver.openOutputStream(targetUri)?.use { out ->
                FileInputStream(dbFile).use { input ->
                    input.copyTo(out)
                }
            } ?: return@withContext Result.failure(IllegalStateException("Unable to open destination file"))
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun restoreDatabaseFromUri(context: Context, sourceUri: Uri): Result<Unit> = withContext(Dispatchers.IO) {
        try {
            val tempFile = File(context.cacheDir, "restore_candidate.db")
            context.contentResolver.openInputStream(sourceUri)?.use { input ->
                FileOutputStream(tempFile).use { out ->
                    input.copyTo(out)
                }
            } ?: return@withContext Result.failure(IllegalStateException("Unable to read backup file"))

            // Basic SQLite header check ("SQLite format 3\u0000")
            val header = ByteArray(16)
            FileInputStream(tempFile).use { it.read(header) }
            val headerStr = String(header, 0, 15, Charsets.US_ASCII)
            if (!headerStr.startsWith("SQLite format 3")) {
                tempFile.delete()
                return@withContext Result.failure(IllegalArgumentException("Invalid SQLite backup file"))
            }

            PosDatabase.closeAndReset()
            val dbFile = context.getDatabasePath(PosDatabase.DB_NAME)
            File(dbFile.absolutePath + "-wal").delete()
            File(dbFile.absolutePath + "-shm").delete()
            tempFile.copyTo(dbFile, overwrite = true)
            tempFile.delete()
            // Re-open fresh instance
            PosDatabase.getInstance(context)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun exportCsvToUri(context: Context, targetUri: Uri, csvContent: String): Result<Unit> =
        withContext(Dispatchers.IO) {
            try {
                context.contentResolver.openOutputStream(targetUri)?.use { out ->
                    out.write(byteArrayOf(0xEF.toByte(), 0xBB.toByte(), 0xBF.toByte())) // UTF-8 BOM for Bangla in Excel
                    out.write(csvContent.toByteArray(Charsets.UTF_8))
                } ?: return@withContext Result.failure(IllegalStateException("Cannot write CSV"))
                Result.success(Unit)
            } catch (e: Exception) {
                Result.failure(e)
            }
        }

    fun buildProductsCsv(products: List<ProductEntity>): String {
        val sb = StringBuilder("ProductCode,Name,Barcode,PurchasePrice,SellingPrice,GPAmount,GPPercent,Stock,MinAlert,Unit\n")
        products.forEach { p ->
            sb.append("${csv(p.productCode)},${csv(p.name)},${csv(p.barcode)},${p.purchasePrice},${p.sellingPrice},${p.gpAmount},${p.gpPercentage},${p.currentStock},${p.minStockAlert},${csv(p.unit)}\n")
        }
        return sb.toString()
    }

    fun buildVendorsCsv(vendors: List<VendorEntity>): String {
        val sb = StringBuilder("VendorCode,Name,ContactPerson,Mobile,AltPhone,Address,Notes\n")
        vendors.forEach { v ->
            sb.append("${csv(v.vendorCode)},${csv(v.name)},${csv(v.contactPerson)},${csv(v.mobile)},${csv(v.altPhone)},${csv(v.address)},${csv(v.notes)}\n")
        }
        return sb.toString()
    }

    fun buildSalesCsv(sales: List<SaleWithItems>): String {
        val sb = StringBuilder("BillNumber,Date,CustomerName,CustomerMobile,TotalQty,Subtotal,Discount,GrandTotal,Status\n")
        sales.forEach { sw ->
            val s = sw.sale
            sb.append("${csv(s.billNumber)},${csv(DhakaTime.formatDateTime(s.createdAt))},${csv(s.customerName)},${csv(s.customerMobile)},${s.totalQuantity},${s.subtotal},${s.discountAmount},${s.grandTotal},${csv(s.status)}\n")
        }
        return sb.toString()
    }

    private fun csv(raw: String): String {
        val escaped = raw.replace("\"", "\"\"")
        return "\"$escaped\""
    }
}

package com.bazarpos.retail.domain

import java.text.NumberFormat
import java.time.Instant
import java.time.LocalDate
import java.time.ZoneId
import java.time.format.DateTimeFormatter
import java.time.temporal.ChronoUnit
import java.util.Locale
import kotlin.math.roundToLong

object DhakaTime {
    val ZONE: ZoneId = ZoneId.of("Asia/Dhaka")
    private val DATE_KEY_FMT = DateTimeFormatter.ofPattern("yyyyMMdd", Locale.US)
    private val DISPLAY_FMT = DateTimeFormatter.ofPattern("dd MMM yyyy, hh:mm a", Locale.US)
    private val SHORT_DATE_FMT = DateTimeFormatter.ofPattern("dd MMM yyyy", Locale.US)

    fun todayDateKey(nowMillis: Long = System.currentTimeMillis()): String {
        return Instant.ofEpochMilli(nowMillis).atZone(ZONE).toLocalDate().format(DATE_KEY_FMT)
    }

    fun formatDateTime(millis: Long): String {
        return Instant.ofEpochMilli(millis).atZone(ZONE).format(DISPLAY_FMT)
    }

    fun formatDate(millis: Long): String {
        return Instant.ofEpochMilli(millis).atZone(ZONE).toLocalDate().format(SHORT_DATE_FMT)
    }

    fun startOfTodayMillis(nowMillis: Long = System.currentTimeMillis()): Long {
        val today = Instant.ofEpochMilli(nowMillis).atZone(ZONE).toLocalDate()
        return today.atStartOfDay(ZONE).toInstant().toEpochMilli()
    }

    fun endOfTodayMillis(nowMillis: Long = System.currentTimeMillis()): Long {
        val tomorrow = Instant.ofEpochMilli(nowMillis).atZone(ZONE).toLocalDate().plusDays(1)
        return tomorrow.atStartOfDay(ZONE).toInstant().toEpochMilli() - 1
    }

    fun startOfMonthMillis(nowMillis: Long = System.currentTimeMillis()): Long {
        val first = Instant.ofEpochMilli(nowMillis).atZone(ZONE).toLocalDate().withDayOfMonth(1)
        return first.atStartOfDay(ZONE).toInstant().toEpochMilli()
    }

    fun startOfYearMillis(nowMillis: Long = System.currentTimeMillis()): Long {
        val first = Instant.ofEpochMilli(nowMillis).atZone(ZONE).toLocalDate().withDayOfYear(1)
        return first.atStartOfDay(ZONE).toInstant().toEpochMilli()
    }
}

data class GpResult(
    val gpAmount: Double,
    val gpPercentage: Double
)

object GpCalculator {
    fun calculate(purchasePrice: Double, sellingPrice: Double): GpResult {
        val safePurchase = purchasePrice.coerceAtLeast(0.0)
        val safeSelling = sellingPrice.coerceAtLeast(0.0)
        val gpAmount = round2(safeSelling - safePurchase)
        val gpPercentage = if (safeSelling > 0.0) {
            round2((gpAmount / safeSelling) * 100.0)
        } else {
            0.0
        }
        return GpResult(gpAmount = gpAmount, gpPercentage = gpPercentage)
    }

    fun round2(value: Double): Double = (value * 100.0).roundToLong() / 100.0
}

object BillNumberGenerator {
    fun nextBillNumber(dateKey: String, latestBillNumberForDate: String?): String {
        val nextSerial = if (latestBillNumberForDate.isNullOrBlank()) {
            1
        } else {
            val parts = latestBillNumberForDate.split("-")
            val lastNum = parts.getOrNull(1)?.toIntOrNull() ?: 0
            lastNum + 1
        }
        return "$dateKey-${nextSerial.toString().padStart(3, '0')}"
    }

    fun nextCode(prefix: String, maxId: Long?, padWidth: Int = 4): String {
        val next = (maxId ?: 0L) + 1L
        return "$prefix-${next.toString().padStart(padWidth, '0')}"
    }
}

object ExchangePolicy {
    const val MAX_EXCHANGE_DAYS = 3L

    fun isEligibleForExchange(saleCreatedAtMillis: Long, nowMillis: Long = System.currentTimeMillis()): Boolean {
        val saleDate: LocalDate = Instant.ofEpochMilli(saleCreatedAtMillis).atZone(DhakaTime.ZONE).toLocalDate()
        val currentDate: LocalDate = Instant.ofEpochMilli(nowMillis).atZone(DhakaTime.ZONE).toLocalDate()
        val daysBetween = ChronoUnit.DAYS.between(saleDate, currentDate)
        return daysBetween in 0..MAX_EXCHANGE_DAYS
    }
}

object CurrencyFormatter {
    fun format(amount: Double, symbol: String = "৳"): String {
        val nf = NumberFormat.getNumberInstance(Locale("en", "BD")).apply {
            minimumFractionDigits = 2
            maximumFractionDigits = 2
        }
        return "$symbol${nf.format(amount)}"
    }
}

